// src/pages/Spares.jsx  – Spare Parts inventory
import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import api, { fmtGHS, fmtDate } from '../utils/api';
import toast from 'react-hot-toast';

export default function SparesPage() {
  const [items,   setItems]   = useState([]);
  const [ledger,  setLedger]  = useState([]);
  const [saving,  setSaving]  = useState(false);
  const [search,  setSearch]  = useState('');
  const [tab,     setTab]     = useState('stock');

  const { register, handleSubmit, reset } = useForm({
    defaultValues: { item_type: 'SPARE_PART', unit: 'pcs' }
  });

  useEffect(() => { load(); }, []);

  const load = () => {
    api.get('/inventory/items/?item_type=SPARE_PART').then(r => setItems(r.data.results || r.data)).catch(() => {});
    api.get('/inventory/closing-stock/?item_type=SPARE_PART').then(r => setLedger(r.data.results || r.data)).catch(() => {});
  };

  const onSubmit = async (data) => {
    setSaving(true);
    try {
      await api.post('/inventory/items/', { ...data, reorder_level: parseFloat(data.reorder_level || 0) });
      toast.success('Spare part item created.');
      reset({ item_type: 'SPARE_PART', unit: 'pcs' });
      load();
    } catch (e) {
      toast.error(e.response?.data?.detail || JSON.stringify(e.response?.data) || 'Failed.');
    } finally { setSaving(false); }
  };

  const deleteItem = async (id) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;
    try {
      await api.delete(`/inventory/items/${id}/`);
      toast.success('Item deleted.');
      load();
    } catch (e) {
      toast.error('Cannot delete item (may be used in stock ledger).');
    }
  };

  const filtered = (tab === 'stock' ? ledger : items).filter(i =>
    (i.item_name || i.name)?.toLowerCase().includes(search.toLowerCase())
  );

  const totalParts = items.length;
  const lowStock   = ledger.filter(s => parseFloat(s.quantity || 0) <= parseFloat(s.reorder_level || 0) && parseFloat(s.quantity || 0) > 0).length;
  const outOfStock = ledger.filter(s => parseFloat(s.quantity || 0) <= 0).length;
  const totalValue = ledger.reduce((s, i) => s + parseFloat(i.quantity || 0) * parseFloat(i.unit_price || 0), 0);

  return (
    <div>
      <div className="kpi-grid mb16" style={{ gridTemplateColumns: 'repeat(4,1fr)' }}>
        {[
          { label: 'Part Types',   val: totalParts,       color: 'var(--blue)',  fmt: false },
          { label: 'Low Stock',    val: lowStock,         color: 'var(--amber)', fmt: false },
          { label: 'Out of Stock', val: outOfStock,       color: 'var(--red)',   fmt: false },
          { label: 'Spare Value',  val: fmtGHS(totalValue), color: 'var(--green)', fmt: true },
        ].map((k, i) => (
          <div key={i} className="kpi">
            <div className="kpi-label">{k.label}</div>
            <div className="kpi-val" style={{ color: k.color, fontSize: k.fmt ? 15 : 22 }}>{k.val}</div>
          </div>
        ))}
      </div>

      <div className="g2">
        {/* Add new item form */}
        <div className="card">
          <div className="card-title"><span className="card-title-ic">🔧</span>Add Spare Part Type</div>
          <form onSubmit={handleSubmit(onSubmit)}>
            <div className="fgrid">
              <div className="fg" style={{ gridColumn: 'span 2' }}>
                <label>Part Name *</label>
                <input type="text" placeholder="e.g. Engine Filter, Brake Pad" {...register('name', { required: true })} />
              </div>
              <div className="fg">
                <label>Unit</label>
                <select {...register('unit')}>
                  <option value="pcs">pcs</option>
                  <option value="set">set</option>
                  <option value="litres">litres</option>
                  <option value="kg">kg</option>
                  <option value="m">m</option>
                </select>
              </div>
              <div className="fg">
                <label>Reorder Level</label>
                <input type="number" step="0.01" min="0" placeholder="5" {...register('reorder_level')} />
              </div>
              <div className="fg" style={{ gridColumn: 'span 2' }}>
                <label>Description</label>
                <textarea rows={2} {...register('description')} />
              </div>
            </div>
            <input type="hidden" {...register('item_type')} value="SPARE_PART" />
            <button type="submit" className="btn btn-primary" disabled={saving} style={{ width: '100%', justifyContent: 'center', marginTop: 8 }}>
              {saving ? '⏳ Saving…' : '+ Add Part Type'}
            </button>
          </form>
        </div>

        {/* Stock / Items list */}
        <div className="card">
          <div className="flex items-center justify-between mb12">
            <div className="card-title" style={{ margin: 0 }}>
              <span className="card-title-ic">📦</span>Spare Parts Inventory
            </div>
            <div className="flex gap8">
              <div className="tabs" style={{ margin: 0, border: 'none' }}>
                {['stock','items'].map(t => (
                  <div key={t} className={`tab ${tab === t ? 'active' : ''}`} onClick={() => setTab(t)} style={{ padding: '5px 10px' }}>
                    {t.charAt(0).toUpperCase() + t.slice(1)}
                  </div>
                ))}
              </div>
              <input type="text" placeholder="Search…" value={search} onChange={e => setSearch(e.target.value)}
                style={{ width: 130, padding: '6px 9px', fontSize: 12 }} />
            </div>
          </div>

          <div className="tbl-wrap" style={{ maxHeight: 420, overflowY: 'auto' }}>
            {tab === 'stock' ? (
              <table>
                <thead>
                  <tr><th>Part Name</th><th>Unit</th><th>Qty</th><th>Reorder</th><th>Value</th><th>Status</th></tr>
                </thead>
                <tbody>
                  {filtered.map((s, i) => {
                    const qty    = parseFloat(s.quantity || 0);
                    const reorder = parseFloat(s.reorder_level || 0);
                    const value  = qty * parseFloat(s.unit_price || 0);
                    const isLow  = qty <= reorder && qty > 0;
                    const isOut  = qty <= 0;
                    return (
                      <tr key={i}>
                        <td style={{ fontWeight: 500 }}>{s.item_name}</td>
                        <td>{s.unit || 'pcs'}</td>
                        <td style={{ fontWeight: 700, color: isOut ? 'var(--red)' : isLow ? '#b45309' : 'var(--text)' }}>
                          {qty.toLocaleString()}
                        </td>
                        <td style={{ color: 'var(--muted)' }}>{reorder}</td>
                        <td className="ced">{fmtGHS(value)}</td>
                        <td>
                          {isOut  && <span className="badge b-red">Out of Stock</span>}
                          {isLow  && !isOut && <span className="badge b-amber">Low</span>}
                          {!isLow && !isOut && <span className="badge b-green">OK</span>}
                        </td>
                      </tr>
                    );
                  })}
                  {filtered.length === 0 && (
                    <tr><td colSpan={6} style={{ textAlign: 'center', color: 'var(--muted)', padding: 24 }}>No stock data</td></tr>
                  )}
                </tbody>
              </table>
            ) : (
              <table>
                <thead>
                  <tr><th>Part Name</th><th>Unit</th><th>Reorder Level</th><th>Description</th><th>Actions</th></tr>
                </thead>
                <tbody>
                  {filtered.map(i => (
                    <tr key={i.id}>
                      <td style={{ fontWeight: 500 }}>{i.name}</td>
                      <td>{i.unit}</td>
                      <td>{i.reorder_level}</td>
                      <td style={{ fontSize: 11, color: 'var(--muted)' }}>{i.description || '—'}</td>
                      <td>
                        <button className="btn btn-danger btn-sm" onClick={() => deleteItem(i.id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                  {filtered.length === 0 && (
                    <tr><td colSpan={5} style={{ textAlign: 'center', color: 'var(--muted)', padding: 24 }}>No items</td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
